"""Nederlands — geloof en praktijk (faith_001 … faith_070)."""

T = {
"faith_001": ("Hoeveel zuilen heeft de islam?", ["5", "4", "6", "7"], "De hadith van Jibril en de hadith overgeleverd door Ibn 'Umar noemen de vijf zuilen van de islam."),
"faith_002": ("Hoe heet de geloofsbelijdenis in de islam?", ["De Shahada", "De Salat", "De Zakat", "De Hajj"], "De Shahada, de geloofsgetuigenis, is de eerste zuil van de islam."),
"faith_003": ("Hoe vaak per dag wordt het verplichte gebed in de islam verricht?", ["5", "3", "4", "7"], "De vijf dagelijkse verplichte gebeden zijn een fundamentele zuil van de islam."),
"faith_004": ("Hoe heet de verplichte liefdadigheid in de islam?", ["Zakat", "Sadaqa", "Waqf", "Kaffara"], "De zakat is de verplichte liefdadigheid, een van de vijf zuilen van de islam."),
"faith_005": ("Hoe heet de verplichte vastenmaand in de islam?", ["Ramadan", "Shawwal", "Rajab", "Muharram"], "De Koran gebiedt het vasten tijdens de maand Ramadan."),
"faith_006": ("Hoe heet de bedevaart naar Mekka, eenmaal in het leven verplicht voor wie ertoe in staat is?", ["Hajj", "'Umra", "I'tikaf", "Tawaf"], "De Koran maakt de Hajj verplicht, ten minste eenmaal in het leven, voor ieder die hem kan ondernemen."),
"faith_007": ("In welke richting keren moslims zich voor het gebed?", ["De Ka'ba, in Mekka", "Jeruzalem", "Medina", "Het oosten"], "De Koran stelde de Ka'ba vast als gebedsrichting (qibla)."),
"faith_008": ("Hoeveel geloofsartikelen (zuilen van de Iman) worden volgens een bekende hadith gewoonlijk onderwezen?", ["6", "4", "5", "7"], "De hadith van Jibril noemt zes geloofsartikelen: Allah, de engelen, de boeken, de boodschappers, de Laatste Dag en de goddelijke beschikking."),
"faith_009": ("Hoe heet de reiniging met water die een moslim vóór elk gebed verricht?", ["Wudu (rituele wassing)", "Tayammum", "Ghusl", "Siwak"], "«Wanneer jullie opstaan voor het gebed, was dan jullie gezichten en jullie handen…»: dit is de wudu."),
"faith_010": ("Wat doen volgens de Koran de «edele schrijvers» (kiraman katibin)?", ["Zij noteren de daden van de mensen", "Zij dragen de Troon", "Zij bewaken het Paradijs", "Zij brengen de regen"], "«Over jullie zijn bewakers, edele schrijvers»: engelen noteren elke daad."),
"faith_011": ("Hoeveel schone namen van Allah noemt de authentieke overlevering?", ["99", "50", "100", "114"], "Een authentieke hadith, overgeleverd door al-Bukhari en Muslim, noemt negenennegentig namen: honderd min één."),
"faith_012": ("Wat betekent Allahs naam «Ar-Rahman»?", ["De Meest Barmhartige", "De Schepper", "De Koning", "De Alwetende"], "Ar-Rahman, de Meest Barmhartige: Zijn barmhartigheid omvat alle dingen."),
"faith_013": ("In Al-Fatiha wordt Allah «Meester» van welke dag genoemd?", ["De Dag des Oordeels", "De vrijdag", "De eerste dag", "De dag van 'Arafa"], "«Meester van de Dag des Oordeels»: de dag waarop ieder zijn daden ontmoet."),
"faith_014": ("Op welke dag van de week roept de Koran de gelovigen op tot het gezamenlijke gebed?", ["Vrijdag", "Maandag", "Zaterdag", "Zondag"], "«Wanneer op vrijdag tot het gebed wordt opgeroepen, haast jullie dan naar het gedenken van Allah.»"),
"faith_015": ("Wie waarborgt volgens de Koran dat de Koran tegen elke verandering bewaard blijft?", ["Allah zelf", "Alleen de engelen", "De geleerden", "De koningen"], "«Voorwaar, Wij hebben de Vermaning neergezonden, en voorwaar, Wij zijn er de Bewaker van.»"),
"faith_016": ("Wat verklaart de Koran over het toetreden tot de religie?", ["Er is geen dwang in de religie", "Het gebeurt onder ede", "Het vereist een getuige", "Het gebeurt bij volwassenheid"], "«Er is geen dwang in de religie: de juiste leiding onderscheidt zich van de dwaling.»"),
"faith_017": ("Wat is de groet van de moslims, een wens van vrede?", ["As-salamu 'alaykum", "Marhaban", "Sabah al-khayr", "Ahlan wa sahlan"], "«As-salamu 'alaykum»: vrede zij met jullie, beantwoord met «wa 'alaykum as-salam»."),
"faith_018": ("Hoe heet het geloof in de eenheid van Allah, het hart van de islam?", ["Tawhid", "Tafsir", "Tajwid", "Tarawih"], "Tawhid, bevestigen dat Allah Eén is, zonder deelgenoot, is het fundament van alle geloof."),
"faith_019": ("Welk Boek openbaarde Allah aan de profeet Musa?", ["De Tawrat (Thora)", "De Injil (Evangelie)", "De Zabur (Psalmen)", "De Koran"], "«Wij zonden de Tawrat neer, waarin leiding en licht was» (5:44)."),
"faith_020": ("Welk Boek gaf Allah aan de profeet 'Isa?", ["De Injil (Evangelie)", "De Tawrat", "De Zabur", "De Bladen van Ibrahim"], "«Wij gaven hem de Injil, waarin leiding en licht was» (5:46)."),
"faith_021": ("Wat moet men volgens de Koran doen wanneer men gegroet wordt?", ["Antwoorden met een betere groet, of hem teruggeven", "Zwijgen", "Naar beneden kijken", "Alleen vrienden antwoorden"], "«Wanneer jullie met een groet worden begroet, groet dan met een betere, of geef hem terug» (4:86)."),
"faith_022": ("Soera Al-A'la noemt «de Bladen» (suhuf) van welke twee profeten?", ["Ibrahim en Musa", "Nuh en Hud", "Dawud en Sulayman", "Zakariyya en Yahya"], "«Dit staat in de vroegere Bladen, de Bladen van Ibrahim en Musa» (87:18-19)."),
"faith_023": ("Hoe heet de engel die de Hel bewaakt, genoemd in de Koran?", ["Malik", "Ridwan", "Mika'il", "Israfil"], "De bewoners van de Hel zullen roepen: «O Malik, laat jouw Heer een einde aan ons maken!» (43:77)."),
"faith_024": ("Hoeveel engelen zullen volgens soera Al-Haqqa de Troon van Allah dragen op de Dag der Opstanding?", ["Acht", "Vier", "Twaalf", "Eén"], "«En op die Dag zullen acht de Troon van jouw Heer boven zich dragen» (69:17)."),
"faith_025": ("Wie is volgens de Koran belast met het wegnemen van de zielen bij de dood?", ["De engel des doods", "Jibril", "De profeet", "De djinn"], "«Zeg: de engel des doods, die over jullie is aangesteld, zal jullie zielen wegnemen» (32:11)."),
"faith_026": ("Waaruit werden de engelen geschapen, volgens een hadith in Sahih Muslim?", ["Uit licht", "Uit vuur", "Uit klei", "Uit water"], "«De engelen werden geschapen uit licht, de djinn uit rookloos vuur, en Adam uit wat jullie is beschreven.»"),
"faith_027": ("Waaruit werden de djinn geschapen, volgens de Koran?", ["Uit rookloos vuur", "Uit licht", "Uit klei", "Uit wind"], "«En Hij schiep de djinn uit een rookloze vuurvlam» (55:15)."),
"faith_028": ("Wie noemt de Koran als verklaarde vijand van de mensen?", ["Satan (ash-Shaytan)", "De engelen", "De dieren", "De nacht"], "«Voorwaar, Satan is een vijand voor jullie; neem hem dus als vijand» (35:6)."),
"faith_029": ("Hoeveel profeten worden «Ulu al-'Azm» (die met vaste wil) genoemd?", ["Vijf: Nuh, Ibrahim, Musa, 'Isa en Muhammad ﷺ", "Drie", "Tien", "Vijfentwintig"], "«Wees geduldig zoals de boodschappers met vaste wil geduldig waren» (46:35); soera Ash-Shura (42:13) noemt deze vijf samen."),
"faith_030": ("Waarop zal worden geblazen om de Opstanding aan te kondigen, volgens de Koran?", ["De Bazuin (as-Sur)", "Een ramshoorn", "Een fluit", "Een bel"], "«Op de Bazuin zal worden geblazen, en wie in de hemelen en op de aarde is zal dood neervallen… dan zal er opnieuw op geblazen worden» (39:68)."),
"faith_031": ("Hoe noemt de Koran datgene waarmee de daden op de Dag der Opstanding gewogen worden?", ["De weegschalen (al-Mawazin)", "Het register", "De brug", "De bazuin"], "«Wij zullen de rechtvaardige weegschalen opstellen op de Dag der Opstanding; geen ziel zal in iets onrecht worden aangedaan» (21:47)."),
"faith_032": ("Welke naam geeft de Koran aan het hoogste niveau van het Paradijs, beloofd aan wie gelooft en het goede doet?", ["Al-Firdaws", "Al-Kawthar", "As-Sirat", "Al-A'raf"], "«Zij die geloven en goede daden verrichten, zullen de Tuinen van Firdaws als verblijf hebben» (18:107)."),
"faith_033": ("Wat is de meest voorkomende naam voor de Hel in de Koran?", ["Jahannam", "Firdaws", "Kawthar", "Tasnim"], "De Koran noemt de Hel tientallen keren «Jahannam», bijvoorbeeld: «Jullie zullen worden verzameld in Jahannam» (3:12)."),
"faith_034": ("Welke geloofszuil bevestigt het vers «Wij hebben alles met maat geschapen»?", ["Het geloof in de goddelijke beschikking (al-qadar)", "Het geloof in engelen", "Het geloof in de Boeken", "Het geloof in de boodschappers"], "«Wij hebben alles volgens een maat (qadar) geschapen» (54:49): niets gebeurt buiten Allahs kennis en wil."),
"faith_035": ("Welke zonde verklaart Allah niet te vergeven aan wie sterft zonder er berouw over te hebben?", ["Shirk (deelgenoten toekennen aan Allah)", "Liegen", "Gierigheid", "Woede"], "«Allah vergeeft niet dat Hem deelgenoten worden toegekend, en Hij vergeeft wat minder is dan dat aan wie Hij wil» (4:48)."),
"faith_036": ("Van wie houdt Allah volgens de Koran onder degenen die gezondigd hebben?", ["Van wie berouw tonen", "Van wie hun zonden verbergen", "Van wie wanhopen", "Van wie anderen de schuld geven"], "«Voorwaar, Allah houdt van wie berouw tonen en Hij houdt van wie zich reinigen» (2:222)."),
"faith_037": ("Wat brengt het vragen om vergeving (istighfar) een volk volgens soera Nuh?", ["Overvloedige regen en zegeningen", "Helemaal niets", "Een droogte", "Een lange slaap"], "«Vraag vergeving aan jullie Heer; voorwaar, Hij is Vergevensgezind. Hij zal de hemel in overvloedige regen over jullie zenden» (71:10-11)."),
"faith_038": ("Wat belooft de Koran aan wie zijn vertrouwen op Allah stelt (tawakkul)?", ["Allah is hem genoeg", "Hij wordt rijk", "Hij wordt nooit ziek", "Hij hoeft niet meer te werken"], "«En wie op Allah vertrouwt, Hij is hem genoeg» (65:3)."),
"faith_039": ("Wat zegt Allah over de smeekbede (du'a) in soera Ghafir?", ["«Roep Mij aan; Ik zal jullie verhoren»", "«Roep alleen 's nachts aan»", "«Roep de engelen aan»", "«Du'a is alleen voor profeten»"], "«Jullie Heer zegt: roep Mij aan; Ik zal jullie verhoren» (40:60)."),
"faith_040": ("Waardoor vinden de harten volgens de Koran rust?", ["Door het gedenken van Allah (dhikr)", "Door geld", "Door slaap", "Door reizen"], "«Is het niet door het gedenken van Allah dat de harten rust vinden?» (13:28)."),
"faith_041": ("Wat is het eerste verplichte gebed van de dag?", ["Al-Fajr (dageraad)", "Adh-Dhuhr (middag)", "Al-'Asr (namiddag)", "Al-'Isha' (nacht)"], "De vijf gebeden zijn, in volgorde: Fajr, Dhuhr, 'Asr, Maghrib en 'Isha'."),
"faith_042": ("Hoeveel rak'a's telt het verplichte Fajr-gebed?", ["Twee", "Drie", "Vier", "Eén"], "Fajr heeft twee rak'a's; Maghrib drie; Dhuhr, 'Asr en 'Isha' elk vier."),
"faith_043": ("Welk verplicht gebed heeft drie rak'a's?", ["Al-Maghrib", "Al-Fajr", "Adh-Dhuhr", "Al-'Isha'"], "Maghrib, direct na zonsondergang, is het enige verplichte gebed met drie rak'a's."),
"faith_044": ("Hoe heet de oproep tot het gebed vanuit de moskee?", ["De adhan", "De khutba", "De tasbih", "De talbiya"], "De adhan wordt door de muezzin (mu'adhdhin) vóór elk van de vijf gebeden geroepen."),
"faith_045": ("Tot waar moeten de armen volgens het vers over de wassing worden gewassen?", ["Tot de ellebogen", "Tot de polsen", "Tot de schouders", "Alleen de handen"], "«Was jullie gezichten en jullie handen tot de ellebogen, strijk over jullie hoofden en was jullie voeten tot de enkels» (5:6)."),
"faith_046": ("Wat staat de Koran toe wanneer er geen water is voor de reiniging vóór het gebed?", ["Tayammum met schone aarde", "Bidden zonder reiniging", "Het gebed uitstellen tot de volgende dag", "Wassen met nat zand"], "«Als jullie geen water vinden, zoek dan schone aarde en strijk daarmee over jullie gezichten en handen» (5:6)."),
"faith_047": ("Hoe heet de preek die de imam vóór het vrijdaggebed houdt?", ["De khutba", "De adhan", "De iqama", "De takbir"], "De vrijdagse khutba wordt in twee delen vanaf de minbar gehouden, vóór het gebed."),
"faith_048": ("Welk deel van de spaartegoeden die een vol jaar zijn aangehouden geeft een moslim als zakat?", ["2,5%", "10%", "25%", "1%"], "De zakat over gespaard geld is een kwart van een tiende, 2,5%, zodra het een maanjaar lang boven de drempel (nisab) ligt."),
"faith_049": ("Welke bijzondere liefdadigheid is verschuldigd aan het einde van de Ramadan, vóór het Eid-gebed?", ["Zakat al-fitr", "Zakat over goud", "De khums", "De kaffara"], "De Profeet ﷺ maakte de zakat al-fitr verplicht, een sa' dadels of gerst, voor elke moslim, jong of oud."),
"faith_050": ("Van wanneer tot wanneer duurt het dagelijkse vasten in de Ramadan volgens de Koran?", ["Van de dageraad tot de nacht", "Van de middag tot de avond", "Van zonsopgang tot de middag", "De hele dag en de hele nacht"], "«Eet en drink totdat de witte draad van de dageraad zich onderscheidt van de zwarte draad, voltooi dan het vasten tot de nacht» (2:187)."),
"faith_051": ("Hoe heet de maaltijd die vóór de dageraad wordt genuttigd door wie gaat vasten?", ["De suhur", "De iftar", "De walima", "De 'aqiqa"], "De Profeet ﷺ zei: «Neem de suhur, want in de suhur is zegen.»"),
"faith_052": ("Hoe heet de maaltijd waarmee het vasten bij zonsondergang wordt verbroken?", ["De iftar", "De suhur", "De tarawih", "De tahajjud"], "De iftar verbreekt het vasten zodra de zon ondergaat, op het tijdstip van het Maghrib-gebed."),
"faith_053": ("Hoeveel feesten (Eids) kent de islam per jaar?", ["Twee: Eid al-Fitr en Eid al-Adha", "Slechts één", "Vier", "Twaalf"], "Eid al-Fitr sluit de maand Ramadan af; Eid al-Adha valt op 10 Dhul-Hijja, tijdens de bedevaart."),
"faith_054": ("Welke gebeurtenis herdenkt Eid al-Adha?", ["Het offer van Ibrahim, afgekocht met een ram", "De geboorte van de Profeet ﷺ", "De slag bij Badr", "De openbaring van de Koran"], "Bereid om zijn zoon te offeren, zag Ibrahim hem afgekocht: «Wij kochten hem af met een groot offer» (37:107)."),
"faith_055": ("In welke maand van de islamitische kalender vindt de bedevaart (hajj) plaats?", ["Dhul-Hijja", "Ramadan", "Muharram", "Rajab"], "De hajj vindt plaats van 8 tot 13 Dhul-Hijja, de twaalfde en laatste maand van het maanjaar."),
"faith_056": ("Op welke dag van Dhul-Hijja staan de pelgrims op de vlakte van 'Arafat?", ["De 9e", "De 1e", "De 10e", "De 27e"], "Het staan bij 'Arafat op 9 Dhul-Hijja is de centrale zuil van de hajj; Eid al-Adha volgt de dag erna."),
"faith_057": ("Uit hoeveel rondgangen om de Ka'ba bestaat een tawaf?", ["Zeven", "Drie", "Vijf", "Tien"], "De tawaf bestaat uit zeven rondgangen om de Ka'ba, tegen de klok in, beginnend bij de Zwarte Steen."),
"faith_058": ("Uit hoeveel gangen tussen As-Safa en Al-Marwa bestaat de sa'y?", ["Zeven", "Twee", "Vier", "Twaalf"], "De sa'y herinnert aan Hajars zoektocht naar water voor Isma'il: zeven gangen, van Safa naar Marwa en terug, elke richting geteld."),
"faith_059": ("Hoe heet de staat van wijding die de pelgrim aanneemt, met zijn twee witte doeken?", ["Ihram", "Tawaf", "Wuquf", "Talbiya"], "In ihram dragen mannen twee ongenaaide doeken en onthoudt de pelgrim zich van parfum, jacht en ruzie."),
"faith_060": ("Met welke woorden begint de talbiya, die pelgrims onderweg naar Mekka herhalen?", ["«Labbayka Allahumma labbayk» (Hier ben ik, o Allah, hier ben ik)", "«Allahu akbar»", "«Subhana Allah»", "«Al-hamdu li-Llah»"], "De talbiya van de Profeet ﷺ was: «Labbayka Allahumma labbayk, labbayka la sharika laka labbayk…»"),
"faith_061": ("Wat doen pelgrims in Mina wanneer zij steentjes naar drie zuilen werpen?", ["De steniging van de jamarat", "De tawaf", "De sa'y", "Het staan bij 'Arafat"], "De ramy al-jamarat herinnert aan Ibrahim die Satan met stenen verjoeg; het gebeurt in Mina tijdens de dagen van Eid."),
"faith_062": ("Waar bevindt zich de Zwarte Steen (al-Hajar al-Aswad)?", ["In een hoek van de Ka'ba", "Op de berg 'Arafat", "In Medina", "Op de top van de berg Hira'"], "Ingezet in de oostelijke hoek van de Ka'ba markeert hij het beginpunt van elke rondgang van de tawaf."),
"faith_063": ("Hoe heet het grote zwarte kleed dat de Ka'ba bedekt?", ["De kiswa", "De hijab", "De minbar", "De mihrab"], "De kiswa, geborduurd met verzen in gouddraad, wordt elk jaar tijdens de bedevaart vervangen."),
"faith_064": ("Hoe heet de «kleine» bedevaart naar Mekka, die op elk moment van het jaar kan worden verricht?", ["De 'umra", "De hajj", "De hijra", "De ziyara"], "De 'umra bestaat uit ihram, tawaf en sa'y; anders dan de hajj is zij niet aan een bepaalde maand gebonden."),
"faith_065": ("Wat betekent Allahs naam «Al-Khaliq»?", ["De Schepper", "De Vergever", "De Voorziener", "De Koning"], "«Hij is Allah, de Schepper (al-Khaliq), de Voortbrenger, de Vormgever» (59:24)."),
"faith_066": ("Wat betekent Allahs naam «Al-Ghafur»?", ["De Vergevensgezinde", "De Schepper", "De Almachtige", "De Vrijgevige"], "«Wanhoop niet aan de barmhartigheid van Allah… Hij is de Vergevensgezinde (al-Ghafur), de Barmhartige» (39:53)."),
"faith_067": ("Wat betekenen de twee namen van Allah «As-Sami'» en «Al-Basir»?", ["De Alhorende en de Alziende", "De Koning en de Rechter", "De Schepper en de Voorziener", "De Eerste en de Laatste"], "Het vers van de Nachtreis eindigt: «Hij is de Horende (as-Sami'), de Ziende (al-Basir)» (17:1)."),
"faith_068": ("Wat betekent «As-Samad», een naam van Allah in soera Al-Ikhlas?", ["Degene van wie allen afhankelijk zijn en die van niemand afhankelijk is", "Degene die vergeeft", "Degene die hoort", "Degene die schept"], "«Allahu as-Samad» (112:2): de absolute Meester tot wie alle schepselen zich wenden voor hun behoeften."),
"faith_069": ("Welke twee namen van Allah openen het Troonvers, direct na «Allah, er is geen god dan Hij»?", ["Al-Hayy en Al-Qayyum (de Eeuwig Levende, de Zelfstandige)", "Ar-Rahman en Ar-Rahim", "Al-Malik en Al-Quddus", "Al-'Aziz en Al-Hakim"], "«Allah! Er is geen god dan Hij, de Eeuwig Levende, de Zelfstandige» (2:255)."),
"faith_070": ("Wat betekent Allahs naam «Ar-Razzaq»?", ["De grote Voorziener", "De Vergever", "De Rechtvaardige", "De Zachtmoedige"], "«Voorwaar, Allah is de Voorziener (ar-Razzaq), de Bezitter van kracht, de Standvastige» (51:58)."),
}
